import java.util.TreeSet;

public class Solution {
    /** Gerenciador de endereços (IPAM) de uma rede Docker: uma sub-rede IPv4 com gateway reservado. */
    static final class Ipam {
        static final int PREFIXO_MIN = 8;
        static final int PREFIXO_MAX = 30;

        private final long rede;
        private final long broadcast;
        private final long gateway;
        private final int prefixo;
        private final long hostsUteis;
        private final TreeSet<Long> usados = new TreeSet<>();
        private final TreeSet<Long> liberados = new TreeSet<>();
        private long proximo; // menor endereço que nunca foi entregue e que pode estar livre

        Ipam(String cidr) {
            this(cidr, null);
        }

        Ipam(String cidr, String gateway) {
            if (cidr == null) throw new IllegalArgumentException("cidr nulo");
            int barra = cidr.indexOf('/');
            if (barra < 0 || cidr.indexOf('/', barra + 1) >= 0) throw new IllegalArgumentException("cidr inválido: " + cidr);
            String sufixo = cidr.substring(barra + 1);
            if (!sufixo.matches("\\d{1,2}")) throw new IllegalArgumentException("prefixo inválido: " + cidr);
            this.prefixo = Integer.parseInt(sufixo);
            if (prefixo < PREFIXO_MIN || prefixo > PREFIXO_MAX) throw new IllegalArgumentException("prefixo fora de 8..30: " + prefixo);
            long endereco = parseIp(cidr.substring(0, barra));
            long tamanho = 1L << (32 - prefixo);
            if ((endereco & (tamanho - 1)) != 0) throw new IllegalArgumentException("bits de host ligados: " + cidr);
            this.rede = endereco;
            this.broadcast = rede + tamanho - 1;
            this.hostsUteis = tamanho - 2;
            if (gateway == null) {
                this.gateway = rede + 1;
            } else {
                long g = parseIp(gateway);
                if (g <= rede || g >= broadcast) throw new IllegalArgumentException("gateway fora da faixa de hosts: " + gateway);
                this.gateway = g;
            }
            this.proximo = rede + 1;
            avancar();
        }

        /** O Docker reserva o endereço de rede, o de broadcast e o gateway. */
        private boolean reservado(long ip) {
            return ip == rede || ip == broadcast || ip == gateway;
        }

        private void avancar() {
            while (proximo < broadcast && (reservado(proximo) || usados.contains(proximo))) proximo++;
        }

        private long dentro(String ip) {
            long v = parseIp(ip);
            if (v < rede || v > broadcast) throw new IllegalArgumentException("fora da sub-rede: " + ip);
            return v;
        }

        String subrede() { return formatar(rede) + "/" + prefixo; }

        String gateway() { return formatar(gateway); }

        String broadcast() { return formatar(broadcast); }

        /** Endereços que podem ser entregues a containers (todos os hosts, menos o gateway). */
        long capacidade() { return hostsUteis - 1; }

        long disponiveis() { return capacidade() - usados.size(); }

        boolean emUso(String ip) { return usados.contains(dentro(ip)); }

        boolean reservado(String ip) { return reservado(dentro(ip)); }

        /** Entrega o menor endereço livre. */
        String alocar() {
            long ip;
            if (!liberados.isEmpty()) {
                ip = liberados.pollFirst();
            } else {
                if (proximo >= broadcast) throw new IllegalStateException("faixa esgotada: " + subrede());
                ip = proximo++;
                avancar();
            }
            usados.add(ip);
            return formatar(ip);
        }

        /** Reserva um endereço específico (como docker run --ip). */
        String alocar(String ip) {
            long v = dentro(ip);
            if (reservado(v)) throw new IllegalArgumentException("endereço reservado: " + ip);
            if (usados.contains(v)) throw new IllegalStateException("endereço em uso: " + ip);
            liberados.remove(v);
            usados.add(v);
            if (v == proximo) avancar();
            return formatar(v);
        }

        /** Devolve o endereço à faixa. false se não estava alocado. */
        boolean liberar(String ip) {
            long v = dentro(ip);
            if (!usados.remove(v)) return false;
            if (v < proximo) liberados.add(v);
            return true;
        }
    }

    static long parseIp(String ip) {
        if (ip == null) throw new IllegalArgumentException("ip nulo");
        String[] partes = ip.split("\\.", -1);
        if (partes.length != 4) throw new IllegalArgumentException("ip inválido: " + ip);
        long valor = 0;
        for (String parte : partes) {
            if (!parte.matches("\\d{1,3}") || (parte.length() > 1 && parte.charAt(0) == '0')) throw new IllegalArgumentException("ip inválido: " + ip);
            int octeto = Integer.parseInt(parte);
            if (octeto > 255) throw new IllegalArgumentException("ip inválido: " + ip);
            valor = (valor << 8) | octeto;
        }
        return valor;
    }

    static String formatar(long ip) {
        return ((ip >> 24) & 255) + "." + ((ip >> 16) & 255) + "." + ((ip >> 8) & 255) + "." + (ip & 255);
    }
}

