import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.util.ArrayList;
import java.util.List;

class SolutionTest {
    static Solution.Ipam rede16() { return new Solution.Ipam("172.18.0.0/16"); }

    static long numero(String ip) {
        long v = 0;
        for (String parte : ip.split("[.]")) v = (v << 8) | Integer.parseInt(parte);
        return v;
    }

    // ---------- criação ----------

    @Test void descreveASubrede() {
        Solution.Ipam ip = rede16();
        assertEquals("172.18.0.0/16", ip.subrede());
        assertEquals("172.18.0.1", ip.gateway());
        assertEquals("172.18.255.255", ip.broadcast());
    }

    @Test void calculaACapacidadeSemRedeBroadcastNemGateway() {
        assertEquals(65_533, rede16().capacidade());
        assertEquals(253, new Solution.Ipam("10.5.0.0/24").capacidade());
        assertEquals(5, new Solution.Ipam("10.5.0.8/29").capacidade());
        assertEquals(1, new Solution.Ipam("10.5.0.4/30").capacidade());
        assertEquals(16_777_213L, new Solution.Ipam("10.0.0.0/8").capacidade());
    }

    @Test void funcionaComPrefixoQueNaoFechaOcteto() {
        Solution.Ipam ip = new Solution.Ipam("192.168.64.0/18");
        assertEquals("192.168.127.255", ip.broadcast());
        assertEquals("192.168.64.1", ip.gateway());
        assertEquals("192.168.64.2", ip.alocar());
        assertEquals(16_381, ip.capacidade());
    }

    @Test void rejeitaCidrInvalido() {
        String[] ruins = {
            "", "172.18.0.0", "172.18.0.0/", "172.18.0.0/7", "172.18.0.0/31", "172.18.0.0/32", "172.18.0.0/33",
            "172.18.0.5/16", "172.18.0/16", "256.0.0.0/16", "172.18.0.0/-1", "a.b.c.d/16", "172.18.0.0/16/1",
            "172.018.0.0/16", "172.18.0.0/016", "172.18.0.0.0/16", " 172.18.0.0/16", "172.18.0.0/ 16"
        };
        for (String ruim : ruins) {
            assertThrows(IllegalArgumentException.class, () -> new Solution.Ipam(ruim), "deveria rejeitar: '" + ruim + "'");
        }
        assertThrows(IllegalArgumentException.class, () -> new Solution.Ipam(null));
    }

    @Test void gatewayPersonalizadoLiberaOPrimeiroEndereco() {
        Solution.Ipam ip = new Solution.Ipam("10.0.0.0/24", "10.0.0.10");
        assertEquals("10.0.0.10", ip.gateway());
        assertEquals(253, ip.capacidade());
        for (int i = 1; i <= 9; i++) assertEquals("10.0.0." + i, ip.alocar());
        assertEquals("10.0.0.11", ip.alocar());
    }

    @Test void rejeitaGatewayInvalido() {
        assertThrows(IllegalArgumentException.class, () -> new Solution.Ipam("10.0.0.0/24", "10.0.0.0"));
        assertThrows(IllegalArgumentException.class, () -> new Solution.Ipam("10.0.0.0/24", "10.0.0.255"));
        assertThrows(IllegalArgumentException.class, () -> new Solution.Ipam("10.0.1.0/24", "10.0.0.5"));
        assertThrows(IllegalArgumentException.class, () -> new Solution.Ipam("10.0.0.0/24", "10.0.1.5"));
        assertThrows(IllegalArgumentException.class, () -> new Solution.Ipam("10.0.0.0/24", "lixo"));
    }

    // ---------- alocação do menor livre ----------

    @Test void alocaDoMenorParaOMaior() {
        Solution.Ipam ip = rede16();
        assertEquals("172.18.0.2", ip.alocar());
        assertEquals("172.18.0.3", ip.alocar());
        assertEquals("172.18.0.4", ip.alocar());
        assertEquals(65_530, ip.disponiveis());
    }

    @Test void atravessaOFimDoOcteto() {
        Solution.Ipam ip = rede16();
        String ultimo = null;
        for (int i = 0; i < 254; i++) ultimo = ip.alocar();
        assertEquals("172.18.0.255", ultimo);
        assertEquals("172.18.1.0", ip.alocar());
        assertEquals("172.18.1.1", ip.alocar());
    }

    @Test void liberadoVoltaComoMenorLivre() {
        Solution.Ipam ip = rede16();
        for (int i = 0; i < 4; i++) ip.alocar(); // .2 .3 .4 .5
        assertTrue(ip.liberar("172.18.0.3"));
        assertEquals("172.18.0.3", ip.alocar());
        assertEquals("172.18.0.6", ip.alocar());
    }

    @Test void variosLiberadosVoltamEmOrdem() {
        Solution.Ipam ip = rede16();
        for (int i = 0; i < 6; i++) ip.alocar(); // .2 até .7
        assertTrue(ip.liberar("172.18.0.6"));
        assertTrue(ip.liberar("172.18.0.3"));
        assertTrue(ip.liberar("172.18.0.5"));
        assertEquals("172.18.0.3", ip.alocar());
        assertEquals("172.18.0.5", ip.alocar());
        assertEquals("172.18.0.6", ip.alocar());
        assertEquals("172.18.0.8", ip.alocar());
    }

    @Test void liberarOMenorDeTodosFazOEnderecoVoltarPrimeiro() {
        Solution.Ipam ip = rede16();
        ip.alocar();
        ip.alocar();
        assertTrue(ip.liberar("172.18.0.2"));
        assertEquals("172.18.0.2", ip.alocar());
        assertEquals("172.18.0.4", ip.alocar());
    }

    // ---------- liberar ----------

    @Test void liberarDuasVezesOuSemAlocarDevolveFalse() {
        Solution.Ipam ip = rede16();
        String a = ip.alocar();
        assertTrue(ip.liberar(a));
        assertFalse(ip.liberar(a));
        assertFalse(ip.liberar("172.18.0.99"));
        assertEquals(65_533, ip.disponiveis());
    }

    @Test void reservadosNuncaSaoLiberados() {
        Solution.Ipam ip = rede16();
        assertFalse(ip.liberar("172.18.0.0"));
        assertFalse(ip.liberar("172.18.0.1"));
        assertFalse(ip.liberar("172.18.255.255"));
        assertEquals("172.18.0.2", ip.alocar());
    }

    @Test void liberarForaDaFaixaOuInvalidoLancaExcecao() {
        Solution.Ipam ip = rede16();
        assertThrows(IllegalArgumentException.class, () -> ip.liberar("172.19.0.2"));
        assertThrows(IllegalArgumentException.class, () -> ip.liberar("172.18.0"));
        assertThrows(IllegalArgumentException.class, () -> ip.liberar(null));
    }

    // ---------- faixa esgotada ----------

    @Test void faixaEsgotadaLancaIllegalState() {
        Solution.Ipam ip = new Solution.Ipam("10.5.0.8/29");
        List<String> dados = new ArrayList<>();
        for (int i = 0; i < 5; i++) dados.add(ip.alocar());
        assertEquals(List.of("10.5.0.10", "10.5.0.11", "10.5.0.12", "10.5.0.13", "10.5.0.14"), dados);
        assertEquals(0, ip.disponiveis());
        assertThrows(IllegalStateException.class, ip::alocar);
        assertThrows(IllegalStateException.class, ip::alocar);
    }

    @Test void depoisDeEsgotarLiberarPermiteAlocarDeNovo() {
        Solution.Ipam ip = new Solution.Ipam("10.5.0.8/29");
        for (int i = 0; i < 5; i++) ip.alocar();
        assertTrue(ip.liberar("10.5.0.12"));
        assertEquals("10.5.0.12", ip.alocar());
        assertThrows(IllegalStateException.class, ip::alocar);
    }

    @Test void umSlash30TemUmEnderecoSo() {
        Solution.Ipam ip = new Solution.Ipam("10.5.0.4/30");
        assertEquals("10.5.0.6", ip.alocar());
        assertThrows(IllegalStateException.class, ip::alocar);
        assertTrue(ip.liberar("10.5.0.6"));
        assertEquals("10.5.0.6", ip.alocar());
    }

    // ---------- endereço específico ----------

    @Test void reservaUmEnderecoEscolhido() {
        Solution.Ipam ip = rede16();
        assertEquals("172.18.0.10", ip.alocar("172.18.0.10"));
        assertTrue(ip.emUso("172.18.0.10"));
        assertEquals(65_532, ip.disponiveis());
    }

    @Test void alocacaoSequencialPulaOEnderecoReservado() {
        Solution.Ipam ip = rede16();
        ip.alocar("172.18.0.10");
        List<String> dados = new ArrayList<>();
        for (int i = 0; i < 10; i++) dados.add(ip.alocar());
        assertEquals(List.of("172.18.0.2", "172.18.0.3", "172.18.0.4", "172.18.0.5", "172.18.0.6", "172.18.0.7", "172.18.0.8", "172.18.0.9", "172.18.0.11", "172.18.0.12"), dados);
    }

    @Test void reservarOProximoEnderecoFazOAlocadorPular() {
        Solution.Ipam ip = rede16();
        ip.alocar("172.18.0.2");
        assertEquals("172.18.0.3", ip.alocar());
        ip.alocar("172.18.0.4");
        ip.alocar("172.18.0.5");
        assertEquals("172.18.0.6", ip.alocar());
    }

    @Test void liberarUmEspecificoOFazVoltarAoMenorLivre() {
        Solution.Ipam ip = rede16();
        ip.alocar("172.18.0.3");
        assertEquals("172.18.0.2", ip.alocar());
        assertEquals("172.18.0.4", ip.alocar());
        assertTrue(ip.liberar("172.18.0.3"));
        assertEquals("172.18.0.3", ip.alocar());
    }

    @Test void liberarEspecificoAindaNaFrenteDoPonteiroNaoVazaEndereco() {
        Solution.Ipam ip = rede16();
        ip.alocar("172.18.0.20");
        assertTrue(ip.liberar("172.18.0.20"));
        for (int i = 2; i <= 20; i++) assertEquals("172.18.0." + i, ip.alocar());
    }

    @Test void reservarUmEnderecoQueEstavaLiberadoOTiraDaFila() {
        Solution.Ipam ip = rede16();
        for (int i = 0; i < 3; i++) ip.alocar(); // .2 .3 .4
        assertTrue(ip.liberar("172.18.0.3"));
        assertEquals("172.18.0.3", ip.alocar("172.18.0.3"));
        assertEquals("172.18.0.5", ip.alocar());
    }

    @Test void especificoInvalidoEmUsoOuReservado() {
        Solution.Ipam ip = rede16();
        ip.alocar("172.18.0.10");
        assertThrows(IllegalStateException.class, () -> ip.alocar("172.18.0.10"));
        assertThrows(IllegalArgumentException.class, () -> ip.alocar("172.18.0.1"));
        assertThrows(IllegalArgumentException.class, () -> ip.alocar("172.18.0.0"));
        assertThrows(IllegalArgumentException.class, () -> ip.alocar("172.18.255.255"));
        assertThrows(IllegalArgumentException.class, () -> ip.alocar("172.17.0.10"));
        assertThrows(IllegalArgumentException.class, () -> ip.alocar("lixo"));
        assertThrows(IllegalArgumentException.class, () -> ip.alocar((String) null));
    }

    // ---------- consultas ----------

    @Test void emUsoEReservado() {
        Solution.Ipam ip = rede16();
        String a = ip.alocar();
        assertTrue(ip.emUso(a));
        assertFalse(ip.emUso("172.18.0.50"));
        assertFalse(ip.emUso("172.18.0.1"));
        assertTrue(ip.reservado("172.18.0.0"));
        assertTrue(ip.reservado("172.18.0.1"));
        assertTrue(ip.reservado("172.18.255.255"));
        assertFalse(ip.reservado(a));
        assertFalse(ip.reservado("172.18.0.99"));
        assertThrows(IllegalArgumentException.class, () -> ip.emUso("10.0.0.1"));
        assertThrows(IllegalArgumentException.class, () -> ip.reservado("10.0.0.1"));
    }

    @Test void gatewayPersonalizadoEReservado() {
        Solution.Ipam ip = new Solution.Ipam("10.0.0.0/24", "10.0.0.10");
        assertTrue(ip.reservado("10.0.0.10"));
        assertFalse(ip.reservado("10.0.0.1"));
        assertThrows(IllegalArgumentException.class, () -> ip.alocar("10.0.0.10"));
        assertFalse(ip.liberar("10.0.0.10"));
    }

    @Test void enderecosLogoForaDaFaixaSaoRejeitados() {
        Solution.Ipam ip = rede16();
        assertThrows(IllegalArgumentException.class, () -> ip.alocar("172.17.255.255"));
        assertThrows(IllegalArgumentException.class, () -> ip.alocar("172.19.0.0"));
        assertThrows(IllegalArgumentException.class, () -> ip.emUso("172.17.255.255"));
        assertThrows(IllegalArgumentException.class, () -> ip.reservado("172.19.0.0"));
        assertThrows(IllegalArgumentException.class, () -> ip.liberar("172.17.255.255"));
        assertThrows(IllegalArgumentException.class, () -> ip.liberar("172.19.0.0"));
    }

    // ---------- escala ----------

    @Test void esgotaUmSlash16Inteiro() {
        Solution.Ipam ip = rede16();
        long inicio = System.nanoTime();
        String ultimo = null;
        for (int i = 0; i < 65_533; i++) ultimo = ip.alocar();
        assertEquals("172.18.255.254", ultimo);
        assertEquals(0, ip.disponiveis());
        assertThrows(IllegalStateException.class, ip::alocar);
        for (int i = 3; i < 65_533; i += 2) {
            String quarto = "172.18." + ((i + 2) >> 8) + "." + ((i + 2) & 255);
            assertTrue(ip.liberar(quarto));
        }
        String anterior = ip.alocar();
        for (int i = 0; i < 100; i++) {
            String atual = ip.alocar();
            assertTrue(numero(atual) > numero(anterior), "deveria crescer: " + anterior + " -> " + atual);
            anterior = atual;
        }
        assertTrue((System.nanoTime() - inicio) / 1_000_000 < 5_000, "deveria levar bem menos de 5 s");
    }

    @Test void umSlash8NaoPrealocaNada() {
        Solution.Ipam ip = new Solution.Ipam("10.0.0.0/8");
        long inicio = System.nanoTime();
        assertEquals("10.0.0.2", ip.alocar());
        assertEquals("10.0.0.3", ip.alocar());
        assertEquals(16_777_211L, ip.disponiveis());
        assertTrue((System.nanoTime() - inicio) / 1_000_000 < 2_000);
    }
}
